    model {
        patient = person "Patient" "A patient who books and manages hospital appointments."

        appointmentSystem = softwareSystem "Appointment System" "Manages hospital appointments for patients." {
            bookingWebApp = container "Booking Web App" "Web application that patients use to view and book appointments." "Web"
            schedulingService = container "Scheduling Service" "Service that manages appointment slots and allocates them to patients." "Service"
        }

        patient -> bookingWebApp "Books appointments through" "HTTPS"
        bookingWebApp -> schedulingService "Requests available appointment slots" "REST"
    }

    views {
        systemContext appointmentSystem "SystemContext" "System context view of the Appointment System" {
            include *
            autoLayout
        }
    }
}

